"""Generate a Siemens NXOpen Python journal"""

from __future__ import annotations

import json

from paramfabric.core.graph import ParameterGraph


def generate_nx_journal(graph: ParameterGraph) -> str:
    """Create a journal that updates named expressions in the active NX part"""
    lines = [
        "# Generated by Paramfabric; run inside Siemens NX with a part open.",
        "import NXOpen",
        "import NXOpen.UF",
        "",
        "session = NXOpen.Session.GetSession()",
        "part = session.Parts.Work",
        "if part is None:",
        "    raise RuntimeError('Open a Siemens NX part before running this journal')",
        "expressions = {expression.Name: expression for expression in part.Expressions}",
    ]
    for parameter in graph.fabric.parameters:
        if parameter.type in {"str", "bool"}:
            continue
        name = parameter.name
        value = format(float(graph.value(name).magnitude), ".15g")
        rhs = f"{value}[{parameter.unit}]"
        lines.extend(
            (
                f"name = {json.dumps(name)}",
                f"rhs = {json.dumps(rhs)}",
                "if name in expressions:",
                "    expressions[name].RightHandSide = rhs",
                "else:",
                "    part.Expressions.CreateExpression(NXOpen.Expression.Type.Number, f'{name}={rhs}')",
            )
        )
    lines.extend(("part.ModelingViews.WorkView.Fit()", ""))
    return "\n".join(lines)
